/**
 * Attach to an `<input>` element or a `<div contentEditable>` to add type-ahead
 * support.
 * @public
 * @since 1.4.10
 */
export abstract class AbstractInputSuggest<T> extends PopoverSuggest<T> {

    /**
     * Limit to the number of elements rendered at once. Set to 0 to disable. Defaults to 100.
     * @public
     * @since 1.4.10
     */
    limit: number;
    /**
     * Accepts an `<input>` text box or a contenteditable div.
     * @param app The app instance.
     * @param textInputEl The input element.
     * @public
     */
    constructor(app: App, textInputEl: HTMLInputElement | HTMLDivElement);

    /**
     * Sets the value into the input element.
     * @param value The value.
     * @public
     * @since 1.4.10
     */
    setValue(value: string): void;
    /**
     * Gets the value from the input element.
     * @public
     * @since 1.4.10
     */
    getValue(): string;

    /**
     * Gets the suggestions for the input element.
     * @param query The query.
     * @example
     * ```ts
     * class MyInputSuggest extends AbstractInputSuggest<string> {
     *     protected override getSuggestions(query: string): string[] {
     *         return ['foo', 'bar'];
     *     }
     * }
     * ```
     * @example
     * ```ts
     * class MyInputSuggest extends AbstractInputSuggest<string> {
     *     protected override async getSuggestions(query: string): Promise<string[]> {
     *         return await Promise.resolve(['foo', 'bar']);
     *     }
     * }
     * ```
     * @public
     * @since 1.5.7
     */
    protected abstract getSuggestions(query: string): T[] | Promise<T[]>;
    /**
     * @public
     * @since 1.6.6
     */
    selectSuggestion(value: T, evt: MouseEvent | KeyboardEvent): void;
    /**
     * Registers a callback to handle when a suggestion is selected by the user.
     * @param callback Called with the selected suggestion.
     * @public
     * @since 1.4.10
     */
    onSelect(callback: (value: T, evt: MouseEvent | KeyboardEvent) => any): this;

}

/**
 * Component for a text input or text area.
 * @public
 * @since 0.9.21
 */
export class AbstractTextComponent<T extends HTMLInputElement | HTMLTextAreaElement> extends ValueComponent<string> {
    /**
     * The input element.
     * @public
     * @since 0.9.7
     */
    inputEl: T;

    /**
     * @param inputEl The input element.
     * @public
     */
    constructor(inputEl: T);
    /**
     * @inheritDoc
     * @public
     * @since 1.2.3
     */
    setDisabled(disabled: boolean): this;
    /**
     * Gets the value of the input element.
     * @public
     * @since 0.9.7
     */
    getValue(): string;
    /**
     * Sets the value of the input element.
     * @param value The value.
     * @public
     * @since 0.9.7
     */
    setValue(value: string): this;
    /**
     * Sets the placeholder of the input element.
     * @param placeholder The placeholder text.
     * @public
     * @since 0.9.7
     */
    setPlaceholder(placeholder: string): this;
    /**
     * Manually invokes the callback registered with `onChange`.
     * @public
     * @since 0.9.21
     */
    onChanged(): void;
    /**
     * Set the callback to be called when the value changes.
     * @param callback Called with the new value.
     * @public
     * @since 0.9.7
     */
    onChange(callback: (value: string) => any): this;
}

/**
 * Adds an icon to the library.
 * @param iconId the icon ID.
 * @param svgContent the content of the SVG.
 * @example
 * ```ts
 * addIcon('my-icon', '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><circle cx="50" cy="50" r="40"/></svg>');
 * ```
 * @public
 */
export function addIcon(iconId: string, svgContent: string): void;

/**
 * This is the API version of the app, which follows the release cycle of the desktop app.
 * Example: '0.13.21'
 * @public
 */
export let apiVersion: string;

/**
 * The main app object.
 * @public
 * @since 0.9.7
 */
export class App {

    /**
     * The keymap.
     * @public
     * @since 0.9.7
     */
    keymap: Keymap;
    /**
     * The root keymap scope of the app.
     * @public
     * @since 0.9.7
     */
    scope: Scope;

    /**
     * The workspace.
     * @public
     * @since 0.9.7
     */
    workspace: Workspace;

    /**
     * The vault.
     * @public
     * @since 0.9.7
     */
    vault: Vault;
    /**
     * @public
     * @since 0.9.7
     */
    metadataCache: MetadataCache;

    /**
     * The file manager.
     * @public
     * @since 0.11.0
     */
    fileManager: FileManager;

    /**
     * The last known user interaction event, to help commands find out what modifier keys are pressed.
     * @public
     * @since 0.12.17
     */
    lastEvent: UserEvent | null;

    /**
     * @public
     * @since 1.10.0
     */
    renderContext: RenderContext;
    /**
     * @public
     * @since 1.11.4
     */
    secretStorage: SecretStorage;

    /**
     * @public
     * @since 1.10.0
     */
    isDarkMode(): boolean;

    /**
     * Retrieve value from `localStorage` for this vault.
     * @param key The key.
     * @returns The value, or `null` if it is not set.
     * @public
     * @since 1.8.7
     */
    loadLocalStorage(key: string): any | null;
    /**
     * Save vault-specific value to `localStorage`. If data is `null`, the entry will be cleared.
     * @param key The key.
     * @param data The value. Must be serializable.
     * @public
     * @since 1.8.7
     */
    saveLocalStorage(key: string, data: unknown | null): void;

}

/**
 * Converts an `ArrayBuffer` to a base64 string.
 * @param buffer The data.
 * @public
 */
export function arrayBufferToBase64(buffer: ArrayBuffer): string;

/**
 * Converts an `ArrayBuffer` to a hex string.
 * @param data The data.
 * @public
 */
export function arrayBufferToHex(data: ArrayBuffer): string;

/**
 * Converts a base64 string to an `ArrayBuffer`.
 * @param base64 The base64 string.
 * @public
 */
export function base64ToArrayBuffer(base64: string): ArrayBuffer;

/**
 * The base class for all components.
 * @public
 * @since 0.10.3
 */
export abstract class BaseComponent {
    /**
     * Whether the component is disabled.
     * @public
     * @since 0.10.3
     */
    disabled: boolean;
    /**
     * Facilitates chaining.
     * @param cb Called with this component.
     * @public
     * @since 0.9.7
     */
    then(cb: (component: this) => any): this;
    /**
     * Set whether the component is disabled.
     * @param disabled `true` to disable, `false` to enable.
     * @public
     * @since 1.2.3
     */
    setDisabled(disabled: boolean): this;
}

/**
 * BasesOptions and the associated sub-types are configuration-driven settings controls
 * which can be provided by a {@link BasesViewRegistration} to expose configuration options
 * to users in the view config menu of the Bases toolbar.
 * @public
 * @since 1.10.0
 */
export type BasesAllOptions = BasesOptions | BasesOptionGroup<BasesOptions>;

/**
 * Represents the serialized format of a Bases query as stored in a `.base` file.
 *
 * @public
 * @since 1.10.0
 */
export interface BasesConfigFile {
    /**
     * @public
     * @since 1.10.0
     */
    filters?: BasesConfigFileFilter;

    /**
     * Configuration for properties in this Base.
     *
     * Valid keys for this object currently include:
     *
     *   - displayName: string
     *
     * @public
     * @since 1.10.0
     */
    properties?: Record<string, Record<string, any>>;
    /**
     * Configuration for formulas used in this Base.
     *
     * Key: Formula property name.
     * Value: Formula string.
     *
     * @public
     * @since 1.10.0
     */
    formulas?: Record<string, string>;
    /**
     * Configuration for summary formulas used in this Base.
     *
     * Key: Summary formula name.
     * Value: Formula string.
     *
     * @public
     * @since 1.10.0
     */
    summaries?: Record<string, string>;
    /**
     * Configuration for views used in this Base.
     *
     * @public
     * @since 1.10.0
     */
    views?: BasesConfigFileView[];

}

/**
 * @public
 * @since 1.10.0
 */
export type BasesConfigFileFilter = string | {
    /**
     * @public
     * @since 1.10.0
     */
    and: BasesConfigFileFilter[];
} | {
    /**
     * @public
     * @since 1.10.0
     */
    or: BasesConfigFileFilter[];
} | {
    /**
     * @public
     * @since 1.10.0
     */
    not: BasesConfigFileFilter[];
};

/**
 * @public
 * @since 1.10.0
 */
export interface BasesConfigFileView {
    /**
     * Unique identifier for the view type. Used to select the correct view renderer.
     *
     * @public
     * @since 1.10.0
     */
    type: string;
    /**
     * Friendly name for this view, displayed in the UI to select between views.
     *
     * @public
     * @since 1.10.0
     */
    name: string;
    /**
     * Additional filters, applied only to this view.
     *
     * @public
     * @since 1.10.0
     */
    filters?: BasesConfigFileFilter;
    /**
     * Configuration for grouping the results of this view.
     *
     * @public
     * @since 1.10.0
     */
    groupBy?: {

    };
    /**
     * Ordered list of the groupBy values to show. When set, only these groups appear, in this order.
     * `null` is the group of entries with no value.
     *
     * @public
     * @since 1.14.3
     */
    groupOrder?: FrontmatterValue[];
    /**
     * An ordered list of the properties to display in this view.
     *
     * @public
     * @since 1.10.0
     */
    order?: string[];
    /**
     * Configuration of summaries to display for each property in this view.
     *
     * Key: Property name.
     * Value: Summary formula name.
     *
     * @public
     * @since 1.10.0
     */
    summaries?: Record<string, string>;

}

